#!/usr/bin/env python3
"""Run the preregistered v16 OpenFOAM CPU environment reproduction gate."""

from __future__ import annotations

import hashlib
import base64
import io
import json
import math
import os
import platform
import re
import shutil
import subprocess
import sys
import tempfile
import tarfile
import urllib.request
from pathlib import Path

OUTPUT = Path("/kaggle/working/openfoam_xfid_v16")
NUM = r"[-+0-9.eE]+"
EMBEDDED_PAYLOAD = ''
EMBEDDED_PAYLOAD_SHA256 = '501d42f10493d58ee4feeda0d2aff627130bd16da8c1ff4df8801c762ee7844c'
EMBEDDED_INVENTORY = ['case_template/0/U', 'case_template/0/p', 'case_template/Allrun', 'case_template/constant/transportProperties', 'case_template/constant/triSurface/allowed_design_domain.stl', 'case_template/constant/triSurface/design_candidate.stl', 'case_template/constant/turbulenceProperties', 'case_template/system/blockMeshDict', 'case_template/system/controlDict', 'case_template/system/fvSchemes', 'case_template/system/fvSolution', 'case_template/system/snappyHexMeshDict', 'case_template/system/surfaceFeatureExtractDict', 'criteria.json', 'fixtures/candidate_v16.stl', 'fixtures/design_domain.stl', 'fixtures/physical_profile.yaml', 'kernel-metadata.json', 'openfoam_package_lock.json']


def require(condition: bool, message: str) -> None:
    if not condition:
        raise RuntimeError(message)


def source_root() -> Path:
    local = Path(__file__).resolve().parent
    if (local / "criteria.json").is_file():
        return local
    payload = base64.b64decode(EMBEDDED_PAYLOAD)
    require(hashlib.sha256(payload).hexdigest() == EMBEDDED_PAYLOAD_SHA256, "embedded fixture payload SHA mismatch")
    payload_id = hashlib.sha256(payload).hexdigest()[:16]
    target = Path(tempfile.gettempdir()) / f"openfoam_xfid_v16_payload_{payload_id}"
    if target.exists():
        inventory = sorted(path.relative_to(target).as_posix() for path in target.rglob("*") if path.is_file())
        require(inventory == sorted(EMBEDDED_INVENTORY), "cached fixture payload inventory mismatch")
    else:
        target.mkdir(parents=True, exist_ok=True)
        with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
            members = archive.getmembers()
            inventory = sorted(member.name for member in members if member.isfile())
            require(inventory == sorted(EMBEDDED_INVENTORY), "embedded fixture payload inventory mismatch")
            require(all(member.isfile() and not Path(member.name).is_absolute() and ".." not in Path(member.name).parts for member in members), "invalid fixture payload member")
            for member in members:
                destination = target / member.name
                destination.parent.mkdir(parents=True, exist_ok=True)
                with archive.extractfile(member) as source, destination.open("wb") as output:
                    shutil.copyfileobj(source, output)
    return target

ROOT = source_root()
CRITERIA = json.loads((ROOT / "criteria.json").read_text())
LOCK = json.loads((ROOT / "openfoam_package_lock.json").read_text())
TEMPLATE = ROOT / "case_template"


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()




def run(command: list[str], *, cwd: Path | None = None) -> str:
    completed = subprocess.run(command, cwd=cwd, check=True, text=True, capture_output=True)
    return completed.stdout.strip()


def self_check() -> None:
    fixture = CRITERIA["fixture"]
    require(sha(ROOT / "criteria.json") == "b5e8d16838882c92f17d192cc5b1b0a1a525360ac4968cf5c40e359cb4f3190b", "criteria SHA mismatch")
    require(sha(ROOT / "openfoam_package_lock.json") == "b5e59f8a7da34820fc3c6bda93b3524204dcaf4fa6e4f7f11d6c46ddddb66746", "package-lock SHA mismatch")
    historical = fixture["historical_reference"]
    require(historical["physical_profile_sha256"] == fixture["physical_profile_sha256"], "historical profile identity mismatch")
    require(historical["problem_id"] == fixture["problem_id"], "historical case identity mismatch")
    require(historical["archive_commit"] == "aa2e9d5f702044419c2a63a1eeea52fb421ab5af", "historical archive commit mismatch")
    metadata = json.loads((ROOT / "kernel-metadata.json").read_text())
    require(metadata == CRITERIA["kernel_metadata_contract"], "Kaggle kernel metadata violates preregistered CPU/no-solver contract")
    require(CRITERIA["immutable"] and CRITERIA["registered_before_run"], "criteria are not preregistered and immutable")
    expected_case_inventory = sorted(path.removeprefix("case_template/") for path in fixture["input_file_sha256"] if path.startswith("case_template/"))
    actual_case_inventory = sorted(path.relative_to(TEMPLATE).as_posix() for path in TEMPLATE.rglob("*") if path.is_file())
    require(actual_case_inventory == expected_case_inventory, "case input inventory differs from preregistration")
    require(sha(ROOT / "fixtures/physical_profile.yaml") == fixture["input_file_sha256"]["fixtures/physical_profile.yaml"], "physical-profile source SHA mismatch")
    require(historical["physical_profile_sha256"] == fixture["physical_profile_sha256"], "physical-profile identity differs from historical reference")
    for relative, expected in fixture["input_file_sha256"].items():
        require(sha(ROOT / relative) == expected, f"case input SHA mismatch: {relative}")
    require(sha(ROOT / "fixtures/candidate_v16.stl") == fixture["candidate_stl_sha256"], "candidate fixture SHA mismatch")
    require(sha(ROOT / "fixtures/design_domain.stl") == fixture["design_domain_stl_sha256"], "design-domain fixture SHA mismatch")
    require(sha(TEMPLATE / "constant/triSurface/design_candidate.stl") == fixture["candidate_stl_sha256"], "case candidate SHA mismatch")
    require(sha(TEMPLATE / "constant/triSurface/allowed_design_domain.stl") == fixture["design_domain_stl_sha256"], "case domain SHA mismatch")
    require(LOCK["version"] == CRITERIA["environment"]["package_version"], "package version mismatch")
    print("XFID v16 fixture and package-lock self-check PASS")


def install_openfoam(work: Path) -> dict:
    os_release = Path("/etc/os-release").read_text()
    release = dict(line.split("=", 1) for line in os_release.splitlines() if "=" in line)
    arch = run(["dpkg", "--print-architecture"])
    require(release.get("ID", "").strip('"') == "ubuntu", f"unsupported OS ID: {release.get('ID')}")
    require(release.get("VERSION_CODENAME", "").strip('"') == LOCK["suite"], "OpenCFD v2512 lock only supports Ubuntu Jammy")
    require(arch == LOCK["architecture"], f"unsupported architecture: {arch}")

    installer = work / "add-debian-repo.sh"
    with installer.open("wb") as stream:
        subprocess.run(["curl", "-fsSL", "https://dl.openfoam.com/add-debian-repo.sh"], check=True, stdout=stream)
    require(sha(installer) == LOCK["official_installer_sha256"], "official repository installer SHA mismatch")
    run(["bash", str(installer)])
    index_records = []
    for name, record in LOCK["indexes"].items():
        target = work / name
        with urllib.request.urlopen(record["url"], timeout=60) as response, target.open("wb") as stream:
            shutil.copyfileobj(response, stream)
        digest = sha(target)
        require(digest == record["sha256"], f"official apt index SHA mismatch for {name}: {digest}")
        index_records.append({"name": name, "url": record["url"], "sha256": digest, "bytes": target.stat().st_size})
    subprocess.run(["apt-get", "update"], check=True)
    pkg_names = list(LOCK["packages"])
    specs = [f"{name}={LOCK['version']}" for name in pkg_names]
    subprocess.run(["apt-get", "download", *specs], cwd=work, check=True)
    package_records = []
    for package in pkg_names:
        package_arch = LOCK["package_architectures"][package]
        deb = work / f"{package}_{LOCK['version']}_{package_arch}.deb"
        require(deb.is_file(), f"apt did not download expected exact package {deb.name}")
        digest = sha(deb)
        require(digest == LOCK["packages"][package], f"{package} SHA256 mismatch: {digest}")
        package_records.append({"name": package, "version": LOCK["version"], "architecture": package_arch, "deb": deb.name, "sha256": digest})
    subprocess.run(["apt-get", "install", "-y", *(str(work / f"{name}_{LOCK['version']}_{LOCK['package_architectures'][name]}.deb") for name in pkg_names)], check=True)

    version = run(["bash", "-lc", "source /opt/openfoam2512/etc/bashrc && foamVersion"])
    require(version == CRITERIA["environment"]["foam_version"], f"foamVersion mismatch: {version}")
    installed = run(["dpkg-query", "-W", "-f=${Package}=${Version}\n", "openfoam2512", "openfoam2512-common", "openfoam2512-tools"]).splitlines()
    require(sorted(installed) == sorted(f"{name}={LOCK['version']}" for name in pkg_names), "installed OpenFOAM package set differs from lock")
    return {"os_id": "ubuntu", "os_version": release.get("VERSION_ID", "").strip('"'), "os_codename": LOCK["suite"], "architecture": arch, "observed_os_release": os_release, "apt_index_records": index_records, "package_records": package_records, "installed_packages": sorted(installed), "foamVersion": version, "official_installer_sha256": sha(installer)}


def blocks(text: str, anchor: str) -> dict[str, str]:
    start = text.find(anchor)
    require(start >= 0, f"missing {anchor}")
    text = text[start + len(anchor):]
    found, depth, name, body, pending = {}, 0, None, [], None
    opened = False
    for line in text.splitlines():
        if not opened:
            if "{" in line:
                opened, depth = True, line.count("{") - line.count("}")
            continue
        if name is None and depth == 1:
            match = re.match(r'^\s*(?:"([^\"]+)"|([\w.+-]+))\s*\{', line)
            if match:
                name, body = match.group(1) or match.group(2), [line]
            else:
                candidate = re.match(r'^\s*(?:"([^\"]+)"|([\w.+-]+))\s*$', line)
                if candidate:
                    pending = candidate.group(1) or candidate.group(2)
                elif pending and line.strip() == "{":
                    name, body, pending = pending, [line], None
        elif name is not None:
            body.append(line)
        delta = line.count("{") - line.count("}")
        if name is not None and depth + delta == 1:
            found[name] = "\n".join(body)
            name, body = None, []
        depth += delta
        if depth <= 0:
            break
    return found


def scalar_values(body: str, expected_faces: int) -> list[float]:
    m = re.search(rf"nonuniform\s+List<scalar>\s+(\d+)\s*\((.*?)\)\s*;", body, re.S)
    if m:
        values = [float(v) for v in re.findall(NUM, m.group(2))]
        require(len(values) == int(m.group(1)) == expected_faces, "OpenFOAM scalar-list length differs from patch nFaces")
        return values
    m = re.search(rf"\bvalue\s+uniform\s+({NUM})\s*;", body) or re.search(rf"\buniform\s+({NUM})\s*;", body)
    require(m is not None, "missing scalar boundary value")
    return [float(m.group(1))] * expected_faces


def mesh_boundary_face_counts(text: str) -> dict[str, int]:
    marker = re.search(r"\bobject\s+boundary\s*;", text)
    require(marker is not None, "mesh boundary header is missing")
    text = text[marker.end():]
    opening = re.search(r"(?m)^\s*\d+\s*$\s*\(", text)
    require(opening is not None, "mesh boundary patch list is missing")
    lines = iter(text[opening.end():].splitlines())
    faces = {}
    for line in lines:
        name = line.strip().strip('"')
        if not name:
            continue
        if name == ")":
            break
        require(re.fullmatch(r"[\w.+-]+", name) is not None, "invalid mesh patch name")
        brace = next(lines, "").strip()
        require(brace == "{", f"missing mesh patch block for {name}")
        body = []
        depth = 1
        for body_line in lines:
            depth += body_line.count("{") - body_line.count("}")
            if depth <= 0:
                break
            body.append(body_line)
        match = re.search(r"\bnFaces\s+(\d+)\s*;", "\n".join(body))
        require(match is not None, f"missing nFaces for mesh patch {name}")
        faces[name] = int(match.group(1))
    return faces


def gate(case: Path, environment: dict) -> dict:
    criteria = CRITERIA["gates"]
    check = (case / "log.checkMesh").read_text(errors="replace")
    fail_counts = [int(value) for value in re.findall(r"^[ \t]*Failed (\d+) mesh checks?\.[ \t]*$", check, re.M)]
    diagnostics = re.findall(r"^[ \t]*\*\*\*.*$", check, re.M)
    concave = re.search(r"Concave cells \(using face planes\) found, number of cells:\s*(\d+)", check)
    cells = re.search(r"cells:\s*(\d+)\s*$", check, re.M)
    require(cells and concave and len(fail_counts) == 1 and len(diagnostics) == 1, "checkMesh output missing or unexpected failure")
    concave_count, cell_count = int(concave.group(1)), int(cells.group(1))
    require(cell_count > 0 and 0 <= concave_count <= cell_count, "invalid checkMesh cell counts")
    require(concave_count / cell_count <= criteria["mesh"]["maximum_concave_cell_fraction"], "concave-cell fraction exceeds registered gate")
    require(fail_counts == [1] and concave_count > 0 and re.fullmatch(r"[ \t]*\*\*\*Concave cells .*number of cells:[ \t]*\d+[ \t]*", diagnostics[0]), "only the single registered concave-cell failure is allowed")

    log = (case / "log.simpleFoam").read_text(errors="replace")
    residuals = {}
    for field in ("Ux", "Uy", "Uz", "p"):
        matches = re.findall(rf"Solving for {field}, Initial residual = {NUM}, Final residual = ({NUM})", log)
        require(matches, f"missing final {field} residual")
        residuals[field] = float(matches[-1])
        require(math.isfinite(residuals[field]) and 0 <= residuals[field] <= criteria["residual_final_max"][field], f"{field} residual gate failed")

    times = [p for p in case.iterdir() if p.is_dir() and p.name.isdigit()]
    latest = max(times, key=lambda p: int(p.name))
    phi_blocks = blocks((latest / "phi").read_text(errors="replace"), "boundaryField")
    face_counts = mesh_boundary_face_counts((case / "constant/polyMesh/boundary").read_text(errors="replace"))
    require(phi_blocks.keys() == face_counts.keys(), "phi and mesh boundary patch inventories differ")
    flux = {name: scalar_values(value, face_counts[name]) for name, value in phi_blocks.items()}
    require(all(math.isfinite(value) for values in flux.values() for value in values), "non-finite patch flux")
    required = {"inlet", "outlet", "sideMin", "sideMax", "top", "bottom", "design_candidate"}
    require(required <= flux.keys(), f"missing flux patches: {sorted(required - flux.keys())}")
    net = sum(map(sum, flux.values()))
    absolute = sum(sum(abs(x) for x in values) for values in flux.values())
    imbalance = abs(net) / (0.5 * absolute)
    require(absolute > 0 and math.isfinite(imbalance) and imbalance <= criteria["normalized_mass_imbalance_max"], "mass imbalance exceeds registered gate")

    data = []
    header = None
    for line in (case / "postProcessing/forceCoeffs/0/coefficient.dat").read_text().splitlines():
        if line.startswith("#"):
            header = line.lstrip("#").split()
        elif line.strip():
            require(header is not None, "force coefficient header is missing")
            row = dict(zip(header, (float(x) for x in line.split())))
            require(all(math.isfinite(value) for value in row.values()), "non-finite force coefficient history")
            data.append(row)
    require(len(data) >= criteria["force_stationarity"]["minimum_rows"], "insufficient force history")
    count = max(criteria["force_stationarity"]["minimum_rows"], math.ceil(len(data) * criteria["force_stationarity"]["tail_fraction"]))
    tail = data[-count:]
    responses = {"Cd": [r["Cd"] for r in tail], "downforce_coefficient": [-r["Cl"] for r in tail]}
    stationarity = {}
    for name, values in responses.items():
        mean = sum(values) / len(values)
        std = math.sqrt(sum((x - mean) ** 2 for x in values) / len(values))
        xbar = (len(values) - 1) / 2
        slope = sum((i - xbar) * (x - mean) for i, x in enumerate(values)) / sum((i - xbar) ** 2 for i in range(len(values)))
        drift = abs(slope * (len(values) - 1))
        rel_std, rel_drift = std / max(abs(mean), 1e-30), drift / max(abs(mean), 1e-30)
        if name == "Cd":
            ok = rel_std <= criteria["force_stationarity"]["relative_std_max"] and rel_drift <= criteria["force_stationarity"]["relative_drift_max"]
        else:
            ok = std <= criteria["force_stationarity"]["absolute_std_max"] and drift <= criteria["force_stationarity"]["absolute_drift_max"]
        require(ok, f"{name} stationarity gate failed")
        stationarity[name] = {"mean": mean, "std": std, "linear_drift": drift, "relative_std": rel_std, "relative_drift": rel_drift, "window_rows": count}
    cd, df = stationarity["Cd"]["mean"], stationarity["downforce_coefficient"]["mean"]
    reproduction = criteria["reproduction"]
    require(abs(cd - reproduction["drag_coefficient_reference"]) / abs(reproduction["drag_coefficient_reference"]) <= reproduction["drag_coefficient_relative_tolerance"], "Cd differs from historical fixture beyond registered tolerance")
    require(abs(df - reproduction["downforce_coefficient_reference"]) <= reproduction["downforce_coefficient_absolute_tolerance"], "downforce coefficient differs from historical fixture beyond registered tolerance")
    return {"status": "PASS", "evidence_class": "environment_reproduction", "mesh": {"cells": cell_count, "concave_cells": concave_count, "concave_fraction": concave_count / cell_count, "raw_failed_check_counts": fail_counts, "interpretation": "exactly one failed check is accepted, and only with the registered concave-cell output"}, "final_residuals": residuals, "mass": {"latest_time": latest.name, "normalized_imbalance": imbalance, "threshold": criteria["normalized_mass_imbalance_max"]}, "stationarity": stationarity, "responses": {"Cd": cd, "downforce_coefficient": df, "drag_N": cd * 0.32, "downforce_N": df * 0.32}, "environment": environment}


def main() -> None:
    global FAILURE_STAGE, RUN_STARTED
    if "--self-check" in sys.argv:
        self_check()
        return
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    require(not OUTPUT.exists(), f"refusing to overwrite prior output: {OUTPUT}")
    OUTPUT.mkdir(parents=True)
    RUN_STARTED = True
    FAILURE_STAGE = "preflight"
    self_check()
    FAILURE_STAGE = "environment_install"
    install = install_openfoam(OUTPUT)
    case = OUTPUT / "case"
    shutil.copytree(TEMPLATE, case)
    for path in case.rglob("*"):
        if path.is_file():
            path.chmod(path.stat().st_mode | 0o200)
    (case / "Allrun").chmod(0o755)
    FAILURE_STAGE = "mesh_and_solver"
    subprocess.run(["bash", "-lc", "source /opt/openfoam2512/etc/bashrc && ./Allrun"], cwd=case, check=True)
    FAILURE_STAGE = "qualification_gate"
    result = gate(case, install)
    result["criteria_sha256"] = sha(ROOT / "criteria.json")
    result["package_lock_sha256"] = sha(ROOT / "openfoam_package_lock.json")
    result["runner_sha256"] = sha(Path(__file__).resolve())
    result["execution_commands"] = {
        "install": "apt-get download openfoam2512=2512.0-2 openfoam2512-common=2512.0-2 openfoam2512-tools=2512.0-2; verify all downloaded SHA-256 values; apt-get install the exact .deb files",
        "version": "source /opt/openfoam2512/etc/bashrc && foamVersion",
        "mesh_and_solver": ["blockMesh", "surfaceFeatureExtract", "snappyHexMesh -overwrite", "checkMesh -allGeometry -allTopology", "simpleFoam"],
    }
    result["historical_reference"] = CRITERIA["fixture"]["historical_reference"]
    result["case_input_sha256"] = CRITERIA["fixture"]["input_file_sha256"]
    result["round_id"] = CRITERIA["round_id"]
    result["kernel_metadata_sha256"] = sha(ROOT / "kernel-metadata.json")
    (OUTPUT / "result.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
    manifest = {"status": "PASS", "criteria_sha256": sha(ROOT / "criteria.json"), "package_lock_sha256": sha(ROOT / "openfoam_package_lock.json"), "kernel_metadata_sha256": sha(ROOT / "kernel-metadata.json"), "runner_sha256": sha(Path(__file__).resolve()), "files": {p.relative_to(OUTPUT).as_posix(): sha(p) for p in sorted(OUTPUT.rglob("*")) if p.is_file()}}
    manifest_path = OUTPUT / "artifact_manifest.json"
    manifest_path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    (OUTPUT / "DONE").write_text(json.dumps({"status": "PASS", "artifact_manifest_sha256": sha(manifest_path), "criteria_sha256": manifest["criteria_sha256"]}, sort_keys=True) + "\n")
    print(json.dumps(result, indent=2, sort_keys=True))


FAILURE_STAGE = "startup"
RUN_STARTED = False


def write_error(exc: Exception) -> None:
    error_path = OUTPUT / "ERROR.json" if RUN_STARTED else OUTPUT.parent / f"openfoam_xfid_v16_startup_ERROR_{os.getpid()}.json"
    if error_path.exists():
        return
    error_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        observed_os_release = Path("/etc/os-release").read_text()
    except OSError as error:
        observed_os_release = f"unavailable: {error}"
    try:
        observed_architecture = subprocess.run(["dpkg", "--print-architecture"], check=True, capture_output=True, text=True).stdout.strip()
    except (OSError, subprocess.CalledProcessError) as error:
        observed_architecture = f"unavailable: {error}"
    data = {"status": "FAIL", "failure_stage": FAILURE_STAGE, "error_type": type(exc).__name__, "error": str(exc), "criteria_sha256": sha(ROOT / "criteria.json"), "package_lock_sha256": sha(ROOT / "openfoam_package_lock.json"), "runner_sha256": sha(Path(__file__).resolve()), "runtime": {"python": platform.python_version(), "platform": platform.platform(), "executable": sys.executable, "os_release": observed_os_release, "architecture": observed_architecture}}
    error_path.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        if "--self-check" not in sys.argv:
            write_error(exc)
        print(f"FAIL_CLOSED: {type(exc).__name__}: {exc}", file=sys.stderr)
        raise
